+                    while (col > margin && (col & 3) != 3 && !(trace[col].gap[lane] & bit)) --col;
+                    while (col >= margin+4 && (col & 3) == 3 && !(gaps[col/4][lane] & bit)) col -= 4;
+                    while (col > margin && !(trace[col].gap[lane] & bit)) --col;
+                    const int run = start-col;
+                    if (run) {
+                        int k = 0;
+                        for (; k < run && min(i,start+1)-k >= 8; k += 8) {
+                            Word u,v;
+                            memcpy(&u,qEnd-i+k,8); memcpy(&v,tEnd-start-1+k,8);
+                            Word x = u ^ v;
+                            Word codes = 3*((x | (x >> 1)) & 0x0101010101010101ULL);
+                            memcpy(ops+nops+k,&codes,8);
+                        }
+                        for (; k < run; ++k)
+                            ops[nops+k] = qEnd[k-i] == tEnd[k-start-1] ? EDLIB_EDOP_MATCH : EDLIB_EDOP_MISMATCH;
+                        nops += run;
+                        i -= run;
+                    }
+                    if (col <= margin) break;
+                    if (trace[col].mv[lane] & bit) { ops[nops++] = EDLIB_EDOP_DELETE; --col; }
+                    else { ops[nops++] = EDLIB_EDOP_INSERT; --i; }
+                }
+                for (; col >= 0; --col) {
+                    if (i > 64) { ops[nops++] = EDLIB_EDOP_INSERT; --i; }
+                    Word bit = i ? Word(1) << (i-1) : 0;
+                    Word gap = trace[col].gap[lane], del = trace[col].mv[lane];
+                    while (gap & ~del & bit) {
+                        ops[nops++] = EDLIB_EDOP_INSERT;
+                        --i;
+                        bit >>= 1;
+                    }
+                    if (!bit || (gap & bit)) ops[nops++] = EDLIB_EDOP_DELETE;
+                    else {
+                        ops[nops++] = qEnd[-i] == tEnd[-col-1] ? EDLIB_EDOP_MATCH : EDLIB_EDOP_MISMATCH;
+                        --i;
+                    }
+                }
+                memset(ops+nops,EDLIB_EDOP_INSERT,i);
+                nops += i;
+                int edits = 0;
+                for (int k = 0; k < nops; ++k) edits += ops[k] != EDLIB_EDOP_MATCH;
+                return Piece{keptRows,nops,edits,visited};
+            };
+            Piece front = piece(0,frontOps), back = piece(1,backOps);
+            if (limit > 128 && keep > 80 && ((front.visited | back.visited) & 0xff000000000000ffULL)) {
+                limit = max(128,limit/2);
+                continue;
+            }
+            limit = chunk;
+            if (front.rows+back.rows > qLeft || front.edits+back.edits > bestScore-cost)
+                return false;
+            qFront += front.rows; qBack += back.rows; tFront += keep; tBack += keep;
+            cost += front.edits+back.edits;
+            std::reverse_copy(frontOps,frontOps+front.ops,path+frontSize);
+            frontSize += front.ops; backSize += back.ops;
+            memcpy(path+capacity-backSize,backOps,back.ops);
+        }
+        const int n = queryLength-qFront-qBack, m = targetLength-tFront-tBack;
+        if (n > 2*chunk || n < 0) return false;
+        // Here the target is the shorter axis. Transpose its edit operations
+        // after using the single-word traceback.
+        write = frontOps;
+        if (m && n) leaf(rTarget+tBack,m,rQuery+qBack,n);
+        else {
+            memset(write,m ? EDLIB_EDOP_INSERT : EDLIB_EDOP_DELETE,m+n);
+            write += m+n;
+        }
+        const int middle = static_cast<int>(write-frontOps);
+        write = path;
+        for (int k = 0; k < middle; ++k) {
+            unsigned char op = frontOps[k];
+            if (op == EDLIB_EDOP_INSERT || op == EDLIB_EDOP_DELETE) frontOps[k] = 3-op;
+            cost += op != EDLIB_EDOP_MATCH;
+        }
+        if (cost != bestScore) return false;
+        memcpy(path+frontSize,frontOps,middle);
+        memmove(path+frontSize+middle,path+capacity-backSize,backSize);
+        write = path+frontSize+middle+backSize;
+        return true;
+    };
+    if (identity && alphabetLength <= 4 && targetLength >= 768 &&
+        pairedPath()) {
+        *alignment = path;
+        *alignmentLength = static_cast<int>(write-path);
+        return EDLIB_STATUS_OK;
+    }
+    write = path;
+
+    // Scalar diagonal windows cover the remaining alphabets and equality rules.
+    auto windowPath = [&](int maxChunk) {
+        const int chunk = 384, margin = 31;
+        const int stride = chunk/64+3;
+        int limit = maxChunk;
+        GapBits trace[chunk];
+        unsigned char reverseOps[2*chunk+64];
+        vector<Word> masks(alphabetLength*stride);
+        int q = 0, t = 0, cost = 0;
+        while (q < queryLength && t < targetLength) {
+            int prefix = 0, available = min(queryLength-q, targetLength-t);
+            if (identity) {
+                while (available-prefix >= 8) {
+                    Word a,b;
+                    memcpy(&a,query+q+prefix,8);
+                    memcpy(&b,target+t+prefix,8);
+                    if (a != b) {
+                        prefix += __builtin_ctzll(a ^ b)/8;
+                        break;
+                    }
+                    prefix += 8;
+                }
+            }
+            while (prefix < available &&
+                   equalityDefinition.areEqual(query[q+prefix],target[t+prefix])) ++prefix;
+            memset(write, EDLIB_EDOP_MATCH, prefix);
+            write += prefix;
+            q += prefix; t += prefix;
+            if (q == queryLength || t == targetLength) break;
+            const int width = min(limit, targetLength-t), qLeft = queryLength-q;
+            const bool last = width == targetLength-t;
+            const int finalBase = max(0,width-1-margin);
+            if (qLeft < finalBase || (last && qLeft > finalBase+64)) {
+                if (limit <= 128) return false;
+                limit = max(128,limit/2);
+                continue;
+            }
+            int span = min(qLeft, finalBase+64);
+            int words = ceilDiv(span,64);
+            for (int w = 0; w < words; ++w) {
+                makeProfile(query+q+64*w,min(64,span-64*w));
+                for (int a = 0; a < alphabetLength; ++a)
+                    masks[a*stride+w] = profile[a];
+            }
+            for (int a = 0; a < alphabetLength; ++a) masks[a*stride+words] = 0;
+            Word pv = ~Word(0), mv = 0;
+            int c = 0;
+            for (; c < min(width,margin+1); ++c) {
+                Word eq = masks[target[t+c]*stride];
+                Word xv = eq | mv;
+                Word xh = (((eq & pv)+pv)^pv) | eq;
+                Word ph = mv | ~(xh | pv);
+                Word mh = pv & xh;
+                trace[c] = GapBits{~(eq | mv), ~(eq | (xh & ~mv))};
+                Word shifted = (ph << 1) | 1;
+                pv = (mh << 1) | ~(xv | shifted);
+                mv = xv & shifted;
+            }
+            if (c < width) {
+                pv = (pv >> 1) | HIGH_BIT_MASK;
+                mv >>= 1;
+                Word low = 0;
+                for (; c < width; ++c) {
+                    const int base = c-margin;
+                    const Word* p = masks.data()+target[t+c]*stride+(base/64);
+                    __uint128_t pair = (static_cast<__uint128_t>(p[1]) << 64) | p[0];
+                    Word eq = static_cast<Word>(pair >> (base%64));
+                    Word xv = eq | mv;
+                    Word xh = (((eq & pv)+pv)^pv) | eq;
+                    Word ph = mv | ~(xh | pv);
+                    Word mh = pv & xh;
+                    // Prefer an optimal diagonal. At a mismatch the diagonal
+                    // costs one exactly when both Xh and the old Mv are clear.
+                    // Mv selects a target-only move on the remaining ties.
+                    trace[c] = GapBits{~(eq | mv), ~(eq | (xh & ~mv))};
+                    low = xv & 1;
+                    xv >>= 1;
+                    // Slide the vertical differences down one query position
+                    // for the next column, extending its old bottom by a gap.
+                    pv = mh | ~(xv | ph);
+                    mv = ph & xv;
+                }
+                pv <<= 1;
+                mv = (mv << 1) | low;
+            }
+
+            int i = qLeft;
+            if (!last) {
+                int score = 0, best = 0;
+                i = finalBase;
+                for (int k = finalBase; k < min(qLeft,finalBase+64); ++k) {
+                    score += int(pv & 1) - int(mv & 1);
+                    pv >>= 1; mv >>= 1;
+                    if (score <= best) { best = score; i = k+1; }
+                }
+            }
+            int keep = last ? width : width-64;
+            Piece piece = recoverWindow([&](int col) { return trace[col]; },width,keep,i,reverseOps);
+            const int queryKept = piece.rows, nops = piece.ops, edits = piece.edits;
+            const Word visited = piece.visited;
+            // Reduce the window before committing if its path approaches a
+            // clipped diagonal. A shorter window follows larger local indels.
+            if (limit > 128 && (visited & 0xff000000000000ffULL)) {
+                limit = max(128,limit/2);
+                continue;
+            }
+            limit = maxChunk;
+            if (edits > bestScore-cost) return false;
+            cost += edits;
+            write = std::reverse_copy(reverseOps,reverseOps+nops,write);
+            q += queryKept;
+            t += keep;
+        }
+        int tail = queryLength-q + (targetLength-t);
+        if (tail != bestScore-cost) return false;
+        memset(write, q < queryLength ? EDLIB_EDOP_INSERT : EDLIB_EDOP_DELETE,tail);
+        write += tail;
+        return true;
+    };
+    bool found = windowPath(384);
+    if (!found) {
+        write = path;
+        found = windowPath(192);
+    }
+    if (found) {
+        *alignment = path;
+        *alignmentLength = static_cast<int>(write-path);
+        return EDLIB_STATUS_OK;
+    }
+    write = path;
+
+    // Transfer a row of scores through successive strips, one word high.
+    // The left and extended top boundaries correspond to actual gap paths.
+    vector<int> prev, next, forward, backward;
+    auto boundary = [&](const unsigned char* q, int n, const unsigned char* t, int m,
+                        int stop, int radius, vector<int>& result) {
+        int left = 0, right = 0;
+        prev.resize(1);
+        prev[0] = 0;
+        for (int i = 0; i < stop; ) {
+            int h = min(64, stop-i);
+            int a = max(0, static_cast<int>(static_cast<long long>(i)*m/n) - radius);
+            int b = static_cast<int>(std::min<long long>(m, static_cast<long long>(i+h)*m/n + radius));
+            makeProfile(q+i, h);
+            next.resize(b-a+1);
+            int score = prev[a-left] + h;
+            next[0] = score;
+            Word pv = ~Word(0), mv = 0;
+            auto column = [&](int j, bool topNeg, bool topPos, int shift) {
+                Word eq = profile[t[j]];
+                Word xv = eq | mv;
+                eq |= topNeg;
+                Word xh = (((eq & pv) + pv) ^ pv) | eq;
+                Word ph = mv | ~(xh | pv);
+                Word mh = pv & xh;
+                score += int((ph >> shift) & 1) - int((mh >> shift) & 1);
+                next[j-a+1] = score;
+                ph = (ph << 1) | topPos;
+                pv = ((mh << 1) | topNeg) | ~(xv | ph);
+                mv = ph & xv;
+            };
+            auto scan = [&](int shift) {
+                for (int j = a; j < right; ++j) {
+                    int delta = prev[j-left+1] - prev[j-left];
+                    column(j, delta < 0, delta > 0, shift);
+                }
+                for (int j = right; j < b; ++j) column(j, false, true, shift);
+            };
+            if (h == 64) scan(63); else scan(h-1);
+            next.swap(prev);
+            left = a;
+            right = b;
+            i += h;
+        }
+        result.swap(prev);
+        return left;
+    };
+
+    // Very short edit scripts have small wavefronts even on long substrings.
+    const int tinyLimit = 12;
+    int ends[(tinyLimit+1)*(tinyLimit+1)];
+    unsigned char pred[(tinyLimit+1)*(tinyLimit+1)];
+    auto tiny = [&](const unsigned char* q, int n, const unsigned char* t, int m, int d) {
+        ends[0] = 0;
+        for (int s = 1; s <= d; ++s) {
+            for (int k = -s; k <= s; ++k) {
+                const int last = (s-1)*s + k, slot = s*(s+1) + k;
+                int x = -1, op = 0;
+                if (k >= 2-s && ends[last-1] >= 0 && ends[last-1] < n) {
+                    x = ends[last-1] + 1;
+                    op = EDLIB_EDOP_INSERT;
+                }
+                if (k > -s && k < s && ends[last] >= 0 && ends[last] < n &&
+                    ends[last] - k < m && ends[last] + 1 >= x) {
+                    x = ends[last] + 1;
+                    op = EDLIB_EDOP_MISMATCH;
+                }
+                if (k <= s-2 && ends[last+1] >= 0 && ends[last+1] > x &&
+                    ends[last+1] - k <= m) {
+                    x = ends[last+1];
+                    op = EDLIB_EDOP_DELETE;
+                }
+                ends[slot] = x;
+                if (x < 0) continue;
+                while (x < n && x-k < m && equalityDefinition.areEqual(q[x], t[x-k])) ++x;
+                ends[slot] = x;
+                pred[slot] = static_cast<unsigned char>(op);
+            }
+        }
+        int k = n-m, x = n;
+        unsigned char edits[tinyLimit];
+        int matches[tinyLimit];
+        if (ends[d*(d+1)+k] != x) return false;
+        for (int s = d; s > 0; --s) {
+            int op = pred[s*(s+1)+k];
+            k += (op == EDLIB_EDOP_DELETE) - (op == EDLIB_EDOP_INSERT);
+            int before = ends[(s-1)*s+k];
+            edits[s-1] = static_cast<unsigned char>(op);
+            matches[s-1] = x-before-(op != EDLIB_EDOP_DELETE);
+            x = before;
+        }
+        for (int s = 0; s < d; ++s) {
+            *write++ = edits[s];
+            memset(write, EDLIB_EDOP_MATCH, matches[s]);
+            write += matches[s];
+        }
+        return true;
+    };
+
+    auto solve = [&](auto&& self, const unsigned char* q, const unsigned char* rq, int n,
+                     const unsigned char* t, const unsigned char* rt, int m, int d) -> bool {
+        int prefix = 0;
+        while (prefix < min(n,m) && equalityDefinition.areEqual(q[prefix],t[prefix])) ++prefix;
+        memset(write, EDLIB_EDOP_MATCH, prefix);
+        write += prefix;
+        n -= prefix; m -= prefix; q += prefix; t += prefix;
+        int suffix = 0;
+        while (suffix < min(n,m) && equalityDefinition.areEqual(rq[suffix],rt[suffix])) ++suffix;
+        n -= suffix; m -= suffix; rq += suffix; rt += suffix;
+        if (!n || !m) {
+            memset(write, n ? EDLIB_EDOP_INSERT : EDLIB_EDOP_DELETE, n+m);
+            write += n+m;
+        } else if (d <= tinyLimit && (d <= 3 || n > 4*d)) {
+            if (!tiny(q,n,t,m,d)) return false;
+        } else if (n <= 64) {
+            leaf(rq,n,rt,m);
+        } else {
+            int mid = n >= 128 ? ((n+64)/128)*64 : n/2;
+            int radius = 8;
+            while (static_cast<long long>(radius)*radius < d) radius *= 2;
+            for (;;) {
+                int a = boundary(q,n,t,m,mid,radius,forward);
+                int b = boundary(rq,n,rt,m,n-mid,radius,backward);
+                const int lo = max(a, m-b-static_cast<int>(backward.size())+1);
+                const int hi = min(a+static_cast<int>(forward.size())-1, m-b);
+                int j = lo;
+                while (j <= hi && forward[j-a] + backward[m-j-b] != d) ++j;
+                if (j <= hi) {
+                    int leftD = forward[j-a];
+                    if (!self(self,q,rq+n-mid,mid,t,rt+m-j,j,leftD)) return false;
+                    if (!self(self,q+mid,rq,n-mid,t+j,rt,m-j,d-leftD)) return false;
+                    break;
+                }
+                if (radius >= m) return false;
+                radius = static_cast<int>(std::min<long long>(m, 2LL*radius));
+            }
+        }
+        memset(write, EDLIB_EDOP_MATCH, suffix);
+        write += suffix;
+        return true;
+    };
+    if (!solve(solve,query,rQuery,queryLength,target,rTarget,targetLength,bestScore)) {
+        free(path);
+        return EDLIB_STATUS_ERROR;
+    }
+    *alignment = path;
+    *alignmentLength = static_cast<int>(write-path);
+    return EDLIB_STATUS_OK;
 }
